package com.bankpli.javabank.credit;import static org.junit.jupiter.api.Assertions.*;import java.time.Duration;import java.util.*;import java.util.concurrent.Executors;import java.util.function.Supplier;import org.junit.jupiter.api.Test;
class CreditServicesTest{@Test void boundaries(){RiskDecisionService s=new RiskDecisionService();assertEquals(CreditDecision.APPROVE,s.decide(720));assertEquals(CreditDecision.CONDITIONAL_REVIEW,s.decide(719));assertEquals(CreditDecision.CONDITIONAL_REVIEW,s.decide(650));assertEquals(CreditDecision.DENY,s.decide(649));}@Test void quorumComputesFromFirstThree(){var pool=Executors.newFixedThreadPool(5);try{CreditScoringService s=new CreditScoringService(pool,new RiskDecisionService(),new TrendAnalyzer());List<Supplier<Integer>>b=List.of(()->720,()->700,()->680,()->{sleep(500);return 400;},()->{sleep(500);return 400;});var result=s.score(b,Duration.ofSeconds(1),List.of(650,655,660,665,670,675,680,685,690,695,700,705));assertEquals(700,result.composite());assertEquals(3,result.responses());}finally{pool.shutdownNow();}}@Test void missingQuorumFails(){var pool=Executors.newFixedThreadPool(5);try{CreditScoringService s=new CreditScoringService(pool,new RiskDecisionService(),new TrendAnalyzer());Supplier<Integer>slow=()->{sleep(200);return 700;};assertThrows(IllegalStateException.class,()->s.score(List.of(()->700,()->710,slow,slow,slow),Duration.ofMillis(50),List.of(650)));}finally{pool.shutdownNow();}}private static void sleep(long ms){try{Thread.sleep(ms);}catch(InterruptedException e){Thread.currentThread().interrupt();}}}
